Lemma exec_eqv_core : forall R R' F F' pc fc rv sz i,
  regs_eqv0 R R' -> regs_eqv F F' ->
  eff_eqv (exec sz i (Core R F pc fc rv)) (exec sz i (Core R' F' pc fc rv)).
